import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

/**
 * Milestone domain rules that need no database: the state error, name
 * normalisation, the overdue test and the listing order. The service layer
 * composes these with the repositories.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const REASON_MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "The milestone is closed.",
  already_open: "The milestone is already open.",
  too_many_open: `A project can hold at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones.`,
  name_taken: "Another milestone in this project already has that name.",
};

/** Raised when a milestone is in the wrong state for the requested change. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    detail?: string,
  ) {
    super(detail ? `${REASON_MESSAGES[reason]} (${detail})` : REASON_MESSAGES[reason]);
    this.name = "MilestoneStateError";
  }
}

export function isMilestoneOpen(milestone: Pick<Milestone, "closedAt">): boolean {
  return milestone.closedAt === null;
}

/** Throws `MilestoneStateError("closed")` unless the milestone is open. */
export function assertMilestoneOpen(
  milestone: Pick<Milestone, "id" | "closedAt">,
): void {
  if (!isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("closed", milestone.id);
  }
}

/** The form names are compared in: case and surrounding spaces are ignored. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

/**
 * Overdue means open, target date strictly before `now`, and still carrying
 * open issues. A milestone without a target date is never overdue.
 */
export function isMilestoneOverdue(
  milestone: Pick<Milestone, "closedAt" | "targetDate">,
  progress: Pick<MilestoneProgress, "open">,
  now: Date,
): boolean {
  if (!isMilestoneOpen(milestone) || milestone.targetDate === null) return false;
  if (progress.open <= 0) return false;
  return Date.parse(milestone.targetDate) < now.getTime();
}

/**
 * Listing order: open before closed, then earliest target date first with
 * undated milestones last, then oldest first. Returns 0 for a full tie, so
 * sorting rows already in insertion order (a stable sort) keeps that order.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const openA = isMilestoneOpen(a);
  if (openA !== isMilestoneOpen(b)) return openA ? -1 : 1;

  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const byTarget = Date.parse(a.targetDate) - Date.parse(b.targetDate);
    if (byTarget !== 0 && !Number.isNaN(byTarget)) return byTarget;
  }

  const byCreation = Date.parse(a.createdAt) - Date.parse(b.createdAt);
  return Number.isNaN(byCreation) ? 0 : byCreation;
}

