/**
 * Milestone rows, their issue counters and the bulk move that closing one performs. Every method takes `orgId` first.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate
 */
import { and, asc, count, eq, inArray, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toMilestone } from "./_mappers";
import type {
  IsoTimestamp,
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

export type NewMilestone = {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
};

export type MilestonePatch = {
  readonly name?: string;
  readonly targetDate?: IsoTimestamp | null;
};

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/**
 * Every milestone of a project, closed ones included, in insertion order —
 * which is what lets callers break a creation-time tie by "oldest first".
 */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(sql`${milestones}.rowid`))
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(input: NewMilestone): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMilestone(row);
}

export async function updateMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  patch: MilestonePatch,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.targetDate === undefined
        ? {}
        : { targetDate: patch.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function reopenMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Closes the milestone and relocates its open live issues in one transaction,
 * so a failure cannot leave a closed milestone still holding open work.
 * Closed (done / canceled) and archived issues are not touched. Returns the
 * ids of the issues that moved, however many there are.
 */
export async function closeMilestone(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveOpenIssuesTo: MilestoneId | null,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const movedRows = tx
      .update(issues)
      .set({ milestoneId: moveOpenIssuesTo, updatedAt: stamp })
      .where(
        and(
          ...compact(
            orgPredicate(issues.orgId, orgId),
            eq(issues.milestoneId, milestoneId),
            livePredicate(issues.archivedAt, {}),
            notInArray(issues.status, [...CLOSED_ISSUE_STATUSES]),
          ),
        ),
      )
      .returning({ id: issues.id })
      .all();

    const row = tx
      .update(milestones)
      .set({ closedAt: stamp, updatedAt: stamp })
      .where(
        and(
          orgPredicate(milestones.orgId, orgId),
          eq(milestones.id, milestoneId),
        ),
      )
      .returning()
      .get();

    if (!row) throw new Error(`Milestone ${milestoneId} not found`);

    return {
      milestone: toMilestone(row),
      movedIssueIds: movedRows.map((moved) => moved.id as IssueId),
    };
  });
}

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

/**
 * Live-issue counters for each milestone, from one grouped query rather than
 * a paged issue list, so the totals are right however many issues there are.
 * Every requested id is present in the result, zeroed when it holds nothing.
 */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const progress = new Map<MilestoneId, MilestoneProgress>(
    milestoneIds.map((id) => [id, EMPTY_PROGRESS]),
  );
  if (milestoneIds.length === 0) return progress;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.milestoneId, [...milestoneIds]),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    const id = row.milestoneId as MilestoneId | null;
    if (id === null) continue;

    const current = progress.get(id) ?? EMPTY_PROGRESS;
    const isClosed = CLOSED_ISSUE_STATUSES.includes(row.status);
    progress.set(id, {
      total: current.total + row.value,
      open: current.open + (isClosed ? 0 : row.value),
      closed: current.closed + (isClosed ? row.value : 0),
    });
  }

  return progress;
}

