/**
 * Milestone lifecycle: create, rename and re-date, close (moving the open issues on), reopen, and the progress read model.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import {
  MilestoneStateError,
  assertMilestoneOpen,
  compareMilestones,
  isMilestoneOpen,
  isMilestoneOverdue,
  milestoneNameKey,
} from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  NotFoundError,
  actorEnvelope,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

/**
 * The alerts for moved issues are sent by the notification fan-out reacting to
 * `milestone.closed`; importing it here guarantees it is attached whenever a
 * milestone can be closed.
 */
import "./notification-service";

/** Loads a project of the org and applies the gates every milestone write shares. */
async function loadProjectForWrite(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

/** Same gates, reached through the milestone rather than its project. */
async function loadMilestoneForWrite(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await loadProjectForWrite(actor, orgId, milestone.projectId);
  return milestone;
}

/**
 * Refuses a name another milestone of the project already uses. Closed
 * milestones count, case and surrounding spaces do not matter, and the
 * milestone being renamed never collides with itself.
 */
function assertNameAvailable(
  siblings: readonly Milestone[],
  name: string,
  renaming: MilestoneId | null,
): void {
  const key = milestoneNameKey(name);
  const taken = siblings.some(
    (sibling) => sibling.id !== renaming && milestoneNameKey(sibling.name) === key,
  );
  if (taken) throw new MilestoneStateError("name_taken");
}

function assertRoomForAnotherOpen(siblings: readonly Milestone[]): void {
  if (siblings.filter(isMilestoneOpen).length >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

/**
 * The milestone an issue may be put into: one of this project (a milestone of
 * another project or workspace is simply not found) that is still open.
 * Shared with `IssueService`, so issue creation and later moves agree.
 */
export async function requireOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  assertMilestoneOpen(milestone);
  return milestone;
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const project = await loadProjectForWrite(actor, input.orgId, input.projectId);

  const siblings = await milestoneRepo.listMilestonesForProject(
    input.orgId,
    project.id,
  );
  assertNameAvailable(siblings, input.name, null);
  assertRoomForAnotherOpen(siblings);

  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name.trim(),
    targetDate: input.targetDate ?? null,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Rename and re-date work on closed milestones too; `null` clears the date. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestoneForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );

  if (input.name !== undefined) {
    const siblings = await milestoneRepo.listMilestonesForProject(
      input.orgId,
      milestone.projectId,
    );
    assertNameAvailable(siblings, input.name, milestone.id);
  }

  if (input.name === undefined && input.targetDate === undefined) {
    return milestone;
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    name: input.name?.trim(),
    targetDate: input.targetDate,
  });
}

/**
 * Closing relocates the milestone's open live issues to the named open
 * milestone of the same project, or out of any milestone when none is named;
 * their assignees are alerted by the notification fan-out. Every refusal is
 * decided before anything is written.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const milestone = await loadMilestoneForWrite(
    actor,
    input.orgId,
    input.milestoneId,
  );
  assertMilestoneOpen(milestone);

  const targetId = input.moveOpenIssuesTo ?? null;
  if (targetId !== null) {
    if (targetId === milestone.id) {
      throw new NotFoundError("Milestone", targetId);
    }
    await requireOpenMilestone(input.orgId, milestone.projectId, targetId);
  }

  const closed = await milestoneRepo.closeMilestone(
    input.orgId,
    milestone.id,
    targetId,
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.milestone.id,
    projectId: closed.milestone.projectId,
    movedToMilestoneId: targetId,
    movedIssueIds: closed.movedIssueIds,
  });

  return closed;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const milestone = await loadMilestoneForWrite(actor, orgId, milestoneId);
  if (isMilestoneOpen(milestone)) {
    throw new MilestoneStateError("already_open", milestone.id);
  }

  assertRoomForAnotherOpen(
    await milestoneRepo.listMilestonesForProject(orgId, milestone.projectId),
  );

  const reopened = await milestoneRepo.reopenMilestone(orgId, milestone.id);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

/** Open milestones first, then closed; see `compareMilestones` for the rest. */
export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [
    ...(await milestoneRepo.listMilestonesForProject(orgId, project.id)),
  ].sort(compareMilestones);

  return withProgress(orgId, milestones);
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [entry] = await withProgress(orgId, [milestone]);
  return requireFound(entry, "Milestone", milestoneId);
}

/** Attaches live-issue counters and the overdue flag, judged at call time. */
async function withProgress(
  orgId: OrgId,
  milestones: readonly Milestone[],
): Promise<readonly MilestoneWithProgress[]> {
  const progress = await milestoneRepo.getMilestoneProgress(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  const now = new Date();

  return milestones.map((milestone) => {
    const counts = progress.get(milestone.id) ?? {
      total: 0,
      open: 0,
      closed: 0,
    };
    return {
      milestone,
      progress: counts,
      overdue: isMilestoneOverdue(milestone, counts, now),
    };
  });
}

