/**
 * Milestones: lifecycle rules, guards, progress, the close-time issue move,
 * and the events, audit rows and alerts they produce.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { isDomainError, toAppError } from "@/lib/errors";
import { MilestoneStateError } from "@/lib/milestones";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import { listNotifications, updatePreference } from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, MilestoneId, ProjectId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(subscribe(type, (payload) => void seen.push(payload)));
  return seen;
}

let sequence = 0;

/** A project of its own, so milestone counts never leak between cases. */
async function freshProject(t: Tenant = tenant): Promise<ProjectId> {
  sequence += 1;
  const project = await projectService.createProject(t.actors.admin, {
    orgId: t.org.id,
    name: `Project ${sequence}`,
    slug: `project-${sequence}`,
    key: `PR${sequence}`,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
  return project.id;
}

async function makeMilestone(
  projectId: ProjectId,
  name: string,
  targetDate: string | null = null,
  t: Tenant = tenant,
) {
  return milestoneService.createMilestone(t.actors.member, {
    orgId: t.org.id,
    projectId,
    name,
    targetDate: targetDate as never,
  });
}

async function makeIssue(
  projectId: ProjectId,
  options: {
    milestoneId?: MilestoneId | null;
    assigneeId?: Tenant["userIds"]["member"] | null;
    status?: IssueStatus;
    archive?: boolean;
  } = {},
) {
  sequence += 1;
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, {
      title: `Issue ${sequence}`,
      assigneeId: options.assigneeId ?? null,
      milestoneId: options.milestoneId ?? null,
    }),
  );
  if (options.status !== undefined) {
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: options.status,
    });
  }
  if (options.archive === true) {
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
  }
  return issue;
}

async function milestoneOf(issueId: IssueId): Promise<MilestoneId | null> {
  return (await issueRepo.findIssueById(tenant.org.id, issueId))?.milestoneId ?? null;
}

async function alertsFor(userId: Tenant["userIds"]["member"]) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: ["issue_milestone_changed"],
    limit: 100,
    cursor: null,
  });
  return page.items;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("milestones");
  other = await createTenant("elsewhere");
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("createMilestone", () => {
  it("creates an open milestone and announces it once", async () => {
    const projectId = await freshProject();
    const seen = capture("milestone.created");

    const milestone = await makeMilestone(projectId, "Beta", "2026-06-30T00:00:00.000Z");

    expect(milestone).toMatchObject({
      orgId: tenant.org.id,
      projectId,
      name: "Beta",
      targetDate: "2026-06-30T00:00:00.000Z",
      closedAt: null,
    });
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      milestoneId: milestone.id,
      projectId,
      actorId: tenant.userIds.member,
      orgId: tenant.org.id,
    });
  });

  it("records one audit row", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Audited");

    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      subjectKind: "milestone",
      action: ["milestone.created"],
      projectId,
      limit: 25,
      cursor: null,
    });

    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "milestone.created",
      subjectKind: "milestone",
      subjectId: milestone.id,
      projectId,
      actorId: tenant.userIds.member,
    });
  });

  it("refuses names that differ only by case or surrounding spaces, closed milestones included", async () => {
    const projectId = await freshProject();
    const first = await makeMilestone(projectId, "Launch");

    await expect(makeMilestone(projectId, "  lAUNCH ")).rejects.toMatchObject({
      reason: "name_taken",
    });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    await expect(makeMilestone(projectId, "LAUNCH")).rejects.toBeInstanceOf(
      MilestoneStateError,
    );
  });

  it("allows the same name in another project", async () => {
    const a = await freshProject();
    const b = await freshProject();
    await makeMilestone(a, "Shared name");
    await expect(makeMilestone(b, "shared name")).resolves.toMatchObject({
      name: "shared name",
    });
  });

  it("refuses an open milestone beyond the cap but does not count closed ones", async () => {
    const projectId = await freshProject();
    const created = [];
    for (let n = 1; n <= MAX_OPEN_MILESTONES_PER_PROJECT; n += 1) {
      created.push(await makeMilestone(projectId, `Open ${n}`));
    }
    const seen = capture("milestone.created");

    await expect(makeMilestone(projectId, "One too many")).rejects.toMatchObject({
      reason: "too_many_open",
    });
    expect(seen).toHaveLength(0);

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: created[0]!.id,
      moveOpenIssuesTo: null,
    });
    await expect(makeMilestone(projectId, "Fits now")).resolves.toBeDefined();
  });

  it("guards scope, existence, permission and archived projects", async () => {
    const projectId = await freshProject();
    const input = { orgId: tenant.org.id, projectId, name: "Guarded", targetDate: null };

    await expect(
      milestoneService.createMilestone(tenant.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      milestoneService.createMilestone(tenant.actors.member, {
        ...input,
        projectId: other.project.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, input),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: true,
    });
    await expect(
      milestoneService.createMilestone(tenant.actors.member, input),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("updateMilestone", () => {
  it("renames and re-dates, including closed milestones, and clears the date with null", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Draft", "2026-06-30T00:00:00.000Z");
    const update = (patch: { name?: string; targetDate?: string | null }) =>
      milestoneService.updateMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        ...(patch as object),
      });

    await expect(update({ name: "DRAFT" })).resolves.toMatchObject({ name: "DRAFT" });
    await expect(update({ targetDate: null })).resolves.toMatchObject({
      name: "DRAFT",
      targetDate: null,
    });
    await expect(update({})).resolves.toMatchObject({ name: "DRAFT" });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });
    await expect(update({ name: "Final" })).resolves.toMatchObject({
      name: "Final",
      closedAt: expect.any(String),
    });
  });

  it("refuses a name another milestone holds", async () => {
    const projectId = await freshProject();
    await makeMilestone(projectId, "Taken");
    const mine = await makeMilestone(projectId, "Mine");

    await expect(
      milestoneService.updateMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: mine.id,
        name: " taken ",
      }),
    ).rejects.toMatchObject({ reason: "name_taken" });
  });

  it("guards scope, existence, permission and archived projects", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Guarded");
    const input = { orgId: tenant.org.id, milestoneId: milestone.id, name: "New" };

    await expect(
      milestoneService.updateMilestone(tenant.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.updateMilestone(other.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.updateMilestone(tenant.actors.viewer, input),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });
    await expect(
      milestoneService.updateMilestone(tenant.actors.member, input),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("closeMilestone", () => {
  it("moves open live issues to the target and leaves closed and archived ones", async () => {
    const projectId = await freshProject();
    const from = await makeMilestone(projectId, "From");
    const to = await makeMilestone(projectId, "To");

    const open = await makeIssue(projectId, { milestoneId: from.id });
    const inReview = await makeIssue(projectId, { milestoneId: from.id, status: "in_review" });
    const done = await makeIssue(projectId, { milestoneId: from.id, status: "done" });
    const canceled = await makeIssue(projectId, { milestoneId: from.id, status: "canceled" });
    const archived = await makeIssue(projectId, { milestoneId: from.id, archive: true });
    const seen = capture("milestone.closed");

    const result = await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: to.id,
    });

    expect(result.milestone.closedAt).toEqual(expect.any(String));
    expect([...result.movedIssueIds].sort()).toEqual([open.id, inReview.id].sort());
    expect(await milestoneOf(open.id)).toBe(to.id);
    expect(await milestoneOf(inReview.id)).toBe(to.id);
    expect(await milestoneOf(done.id)).toBe(from.id);
    expect(await milestoneOf(canceled.id)).toBe(from.id);
    expect(await milestoneOf(archived.id)).toBe(from.id);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      milestoneId: from.id,
      projectId,
      movedToMilestoneId: to.id,
      actorId: tenant.userIds.member,
    });
    expect([...seen[0]!.movedIssueIds].sort()).toEqual([open.id, inReview.id].sort());
  });

  it("takes the open issues out of any milestone when no target is named, however many there are", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Big");

    const total = 150;
    for (let number = 1; number <= total; number += 1) {
      await issueRepo.insertIssue(
        issueInput(tenant.org.id, projectId, { milestoneId: milestone.id }),
        tenant.userIds.member,
        number,
      );
    }

    const before = (await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      milestone.id,
    )).progress;
    expect(before).toEqual({ total, open: total, closed: 0 });

    const result = await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    expect(result.movedIssueIds).toHaveLength(total);
    const after = await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      milestone.id,
    );
    expect(after.progress).toEqual({ total: 0, open: 0, closed: 0 });
  });

  it("alerts each moved issue's assignee once, never the closer, never nobody", async () => {
    const projectId = await freshProject();
    const from = await makeMilestone(projectId, "Alert from");
    const to = await makeMilestone(projectId, "Alert to");

    await makeIssue(projectId, { milestoneId: from.id, assigneeId: tenant.userIds.admin });
    await makeIssue(projectId, { milestoneId: from.id, assigneeId: tenant.userIds.admin });
    await makeIssue(projectId, { milestoneId: from.id, assigneeId: tenant.userIds.owner });
    await makeIssue(projectId, { milestoneId: from.id, assigneeId: tenant.userIds.member });
    await makeIssue(projectId, { milestoneId: from.id });
    await makeIssue(projectId, {
      milestoneId: from.id,
      assigneeId: tenant.userIds.viewer,
      status: "done",
    });

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: to.id,
    });

    expect(await alertsFor(tenant.userIds.admin)).toHaveLength(2);
    expect(await alertsFor(tenant.userIds.owner)).toHaveLength(1);
    expect(await alertsFor(tenant.userIds.member)).toHaveLength(0);
    expect(await alertsFor(tenant.userIds.viewer)).toHaveLength(0);
  });

  it("applies the recipient's notification preferences", async () => {
    const projectId = await freshProject();
    const from = await makeMilestone(projectId, "Muted from");

    await updatePreference(tenant.actors.owner, {
      orgId: tenant.org.id,
      userId: tenant.userIds.owner,
      kind: "issue_milestone_changed",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await makeIssue(projectId, { milestoneId: from.id, assigneeId: tenant.userIds.owner });
    const before = (await alertsFor(tenant.userIds.owner)).length;

    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: from.id,
      moveOpenIssuesTo: null,
    });

    expect(await alertsFor(tenant.userIds.owner)).toHaveLength(before);
  });

  it("records one audit row", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Audited close");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    const page = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["milestone.closed"],
      projectId,
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      subjectKind: "milestone",
      subjectId: milestone.id,
      actorId: tenant.userIds.member,
    });
  });

  it("refuses closing a closed milestone", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Twice");
    const input = {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    };
    await milestoneService.closeMilestone(tenant.actors.member, input);
    const seen = capture("milestone.closed");

    await expect(
      milestoneService.closeMilestone(tenant.actors.member, input),
    ).rejects.toMatchObject({ reason: "closed" });
    expect(seen).toHaveLength(0);
  });

  it("refuses a bad target, changing and announcing nothing", async () => {
    const projectId = await freshProject();
    const otherProjectId = await freshProject();
    const from = await makeMilestone(projectId, "Refused");
    const closedTarget = await makeMilestone(projectId, "Closed target");
    const foreign = await makeMilestone(otherProjectId, "Foreign");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });
    const issue = await makeIssue(projectId, { milestoneId: from.id });
    const seen = capture("milestone.closed");

    const close = (moveOpenIssuesTo: MilestoneId) =>
      milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: from.id,
        moveOpenIssuesTo,
      });

    await expect(close(closedTarget.id)).rejects.toMatchObject({ reason: "closed" });
    await expect(close(from.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close(foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(close("01HZZZNNNNNNNNNNNNNNNNNNNN" as MilestoneId)).rejects.toBeInstanceOf(
      NotFoundError,
    );

    expect(seen).toHaveLength(0);
    expect(await milestoneOf(issue.id)).toBe(from.id);
    const listed = await milestoneService.getMilestone(
      tenant.actors.member,
      tenant.org.id,
      from.id,
    );
    expect(listed.milestone.closedAt).toBeNull();
  });

  it("guards scope, existence, permission and archived projects", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Guarded close");
    const input = {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    };

    await expect(
      milestoneService.closeMilestone(tenant.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.closeMilestone(other.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.viewer, input),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });
    await expect(
      milestoneService.closeMilestone(tenant.actors.member, input),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("reopenMilestone", () => {
  it("reopens a closed milestone and announces it once", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Again");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });
    const seen = capture("milestone.reopened");

    const reopened = await milestoneService.reopenMilestone(
      tenant.actors.member,
      tenant.org.id,
      milestone.id,
    );

    expect(reopened.closedAt).toBeNull();
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ milestoneId: milestone.id, projectId });
  });

  it("refuses an open milestone", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Never closed");
    const seen = capture("milestone.reopened");

    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, milestone.id),
    ).rejects.toMatchObject({ reason: "already_open" });
    expect(seen).toHaveLength(0);
  });

  it("refuses when the project already holds the maximum of open milestones", async () => {
    const projectId = await freshProject();
    const first = await makeMilestone(projectId, "First");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    for (let n = 1; n <= MAX_OPEN_MILESTONES_PER_PROJECT; n += 1) {
      await makeMilestone(projectId, `Filler ${n}`);
    }

    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, first.id),
    ).rejects.toMatchObject({ reason: "too_many_open" });
  });

  it("guards scope, existence, permission and archived projects", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Guarded reopen");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, other.org.id, milestone.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.reopenMilestone(other.actors.member, other.org.id, milestone.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.reopenMilestone(tenant.actors.viewer, tenant.org.id, milestone.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });
    await expect(
      milestoneService.reopenMilestone(tenant.actors.member, tenant.org.id, milestone.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("listMilestones / getMilestone", () => {
  it("lists open before closed, by target date with undated last, ties oldest first", async () => {
    const projectId = await freshProject();
    const undatedOld = await makeMilestone(projectId, "Undated old");
    const late = await makeMilestone(projectId, "Late", "2027-01-01T00:00:00.000Z");
    const early = await makeMilestone(projectId, "Early", "2026-01-01T00:00:00Z");
    const tieA = await makeMilestone(projectId, "Tie A", "2026-06-01T00:00:00.000Z");
    const tieB = await makeMilestone(projectId, "Tie B", "2026-06-01T00:00:00.000Z");
    const undatedNew = await makeMilestone(projectId, "Undated new");
    const closedEarly = await makeMilestone(projectId, "Closed early", "2025-01-01T00:00:00.000Z");
    const closedUndated = await makeMilestone(projectId, "Closed undated");
    for (const milestone of [closedUndated, closedEarly]) {
      await milestoneService.closeMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      });
    }

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );

    expect(listed.map((entry) => entry.milestone.id)).toEqual([
      early.id,
      tieA.id,
      tieB.id,
      late.id,
      undatedOld.id,
      undatedNew.id,
      closedEarly.id,
      closedUndated.id,
    ]);
  });

  it("counts progress over live issues only and flags overdue ones", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-05-01T12:00:00.000Z"));

    const projectId = await freshProject();
    const past = await makeMilestone(projectId, "Past due", "2026-04-30T00:00:00.000Z");
    const pastDone = await makeMilestone(projectId, "Past but done", "2026-04-30T00:00:00.000Z");
    const pastEmpty = await makeMilestone(projectId, "Past and empty", "2026-04-30T00:00:00.000Z");
    const future = await makeMilestone(projectId, "Future", "2026-05-02T00:00:00.000Z");
    const exactly = await makeMilestone(projectId, "Right now", "2026-05-01T12:00:00.000Z");
    const undated = await makeMilestone(projectId, "Undated");

    for (const milestone of [past, future, exactly, undated]) {
      await makeIssue(projectId, { milestoneId: milestone.id });
    }
    await makeIssue(projectId, { milestoneId: past.id, status: "done" });
    await makeIssue(projectId, { milestoneId: past.id, archive: true });
    await makeIssue(projectId, { milestoneId: pastDone.id, status: "canceled" });

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );
    const byName = new Map(listed.map((entry) => [entry.milestone.name, entry]));

    expect(byName.get("Past due")).toMatchObject({
      progress: { total: 2, open: 1, closed: 1 },
      overdue: true,
    });
    expect(byName.get("Past but done")).toMatchObject({
      progress: { total: 1, open: 0, closed: 1 },
      overdue: false,
    });
    expect(byName.get("Past and empty")).toMatchObject({
      progress: { total: 0, open: 0, closed: 0 },
      overdue: false,
    });
    expect(byName.get("Future")?.overdue).toBe(false);
    expect(byName.get("Right now")?.overdue).toBe(false);
    expect(byName.get("Undated")?.overdue).toBe(false);
    expect(pastEmpty.closedAt).toBeNull();
  });

  it("never calls a closed milestone overdue", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-05-01T12:00:00.000Z"));

    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Closed late", "2026-04-01T00:00:00.000Z");
    await makeIssue(projectId, { milestoneId: milestone.id });
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    const read = await milestoneService.getMilestone(
      tenant.actors.viewer,
      tenant.org.id,
      milestone.id,
    );
    expect(read.overdue).toBe(false);
  });

  it("still lists and reads for an archived project", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Survives");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: true,
    });

    const listed = await milestoneService.listMilestones(
      tenant.actors.viewer,
      tenant.org.id,
      projectId,
    );
    expect(listed.map((entry) => entry.milestone.id)).toEqual([milestone.id]);
    await expect(
      milestoneService.getMilestone(tenant.actors.viewer, tenant.org.id, milestone.id),
    ).resolves.toMatchObject({ milestone: { id: milestone.id } });
  });

  it("guards scope and existence", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Hidden");

    await expect(
      milestoneService.listMilestones(tenant.actors.viewer, other.org.id, projectId),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.listMilestones(other.actors.viewer, other.org.id, projectId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.getMilestone(tenant.actors.viewer, other.org.id, milestone.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.getMilestone(other.actors.viewer, other.org.id, milestone.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("issues and milestones", () => {
  it("creates an issue directly into an open milestone of its project", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Home");

    const issue = await makeIssue(projectId, { milestoneId: milestone.id });
    expect(issue.milestoneId).toBe(milestone.id);
    expect(await milestoneOf(issue.id)).toBe(milestone.id);
  });

  it("refuses a creation into a closed, foreign or unknown milestone, creating and announcing nothing", async () => {
    const projectId = await freshProject();
    const otherProjectId = await freshProject();
    const closed = await makeMilestone(projectId, "Closed home");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await makeMilestone(otherProjectId, "Foreign home");
    const elsewhere = await makeMilestone(other.project.id, "Other workspace", null, other);
    const seen = capture("issue.created");
    const before = await issueRepo.countIssues(tenant.org.id, projectId);

    const create = (milestoneId: MilestoneId) =>
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, projectId, { milestoneId }),
      );

    await expect(create(closed.id)).rejects.toMatchObject({ reason: "closed" });
    await expect(create(foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(create(elsewhere.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(create("01HZZZNNNNNNNNNNNNNNNNNNNN" as MilestoneId)).rejects.toBeInstanceOf(
      NotFoundError,
    );

    expect(seen).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, projectId)).toBe(before);
  });

  it("moves an issue between milestones and takes it out", async () => {
    const projectId = await freshProject();
    const a = await makeMilestone(projectId, "A");
    const b = await makeMilestone(projectId, "B");
    const issue = await makeIssue(projectId);
    const set = (milestoneId: MilestoneId | null) =>
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId,
      });

    await expect(set(a.id)).resolves.toMatchObject({ id: issue.id, milestoneId: a.id });
    await expect(set(b.id)).resolves.toMatchObject({ milestoneId: b.id });
    await expect(set(b.id)).resolves.toMatchObject({ milestoneId: b.id });
    await expect(set(null)).resolves.toMatchObject({ milestoneId: null });
    expect(await milestoneOf(issue.id)).toBeNull();
  });

  it("refuses a move into a closed, foreign or unknown milestone", async () => {
    const projectId = await freshProject();
    const otherProjectId = await freshProject();
    const closed = await makeMilestone(projectId, "Closed");
    await milestoneService.closeMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await makeMilestone(otherProjectId, "Foreign");
    const issue = await makeIssue(projectId);
    const set = (milestoneId: MilestoneId) =>
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId,
      });

    await expect(set(closed.id)).rejects.toBeInstanceOf(MilestoneStateError);
    await expect(set(foreign.id)).rejects.toBeInstanceOf(NotFoundError);
    await expect(set("01HZZZNNNNNNNNNNNNNNNNNNNN" as MilestoneId)).rejects.toBeInstanceOf(
      NotFoundError,
    );
    expect(await milestoneOf(issue.id)).toBeNull();
  });

  it("applies the issue:update rules, with the author and assignee escalation", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Escalation");
    const mine = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, projectId, { assigneeId: tenant.userIds.viewer }),
    );
    const notMine = await makeIssue(projectId);

    // The viewer is the assignee of `mine`, which escalates to issue:update.
    await expect(
      issueService.setIssueMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: mine.id,
        milestoneId: milestone.id,
      }),
    ).resolves.toMatchObject({ milestoneId: milestone.id });

    await expect(
      issueService.setIssueMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: notMine.id,
        milestoneId: milestone.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: other.org.id,
        issueId: notMine.id,
        milestoneId: milestone.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.setIssueMilestone(other.actors.member, {
        orgId: other.org.id,
        issueId: notMine.id,
        milestoneId: milestone.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses to move an archived issue or an issue of an archived project", async () => {
    const projectId = await freshProject();
    const milestone = await makeMilestone(projectId, "Frozen");
    const archivedIssue = await makeIssue(projectId, { archive: true });
    const liveIssue = await makeIssue(projectId, { milestoneId: milestone.id });

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: archivedIssue.id,
        milestoneId: milestone.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId,
      archiveIssues: false,
    });
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: liveIssue.id,
        milestoneId: null,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect(await milestoneOf(liveIssue.id)).toBe(milestone.id);
  });
});

describe("errors", () => {
  it("maps MilestoneStateError to a conflict and recognises it as a domain error", () => {
    const error = new MilestoneStateError("too_many_open");
    expect(error.code).toBe("conflict");
    expect(error.reason).toBe("too_many_open");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error).code).toBe("conflict");
  });
});

