      milestoneService.closeMilestone(tenant.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.closeMilestone(other.actors.member, { ...input, orgId: other.org.id }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(tenant.actors.viewer, input),
